mapper.select:
SELECT         mem_seq
FROM         mem_tb
WHERE         mem_seq = #{mem_seq}
And            mem_pw = #{mem_pw}

mapper.update:
UPDATE          mem_tb
SET          mem_pw= #{mem_pw}
            , mem_birth = #{mem_birth}
            , mem_postcd = #{mem_postcd}
            , mem_adrs = #{mem_adrs}
            , mem_detail_adrs = #{mem_detail_adrs}
